def missing_required(car):
    """Список подписей незаполненных обязательных полей."""
    out = []
    for key in REQUIRED:
        val = car.get(key)
        if key == "photos":
            if not val:
                out.append(LABEL[key])
            continue
        if key == "published":
            continue  # bool, False — это осознанный выбор
        if val in (None, "", 0, []):
            out.append(LABEL[key])
    return out

def card_of(card_id):
    card = db.get_card("cars", int(card_id))
    if not card:
        return None
    # старые значения подтягиваем в новые поля, если новые пустые
